//! Text rectangles of the preset geometries, evaluated from ECMA-376's presetShapeDefinitions
//! guide formulas (`preset_text.txt`, generated by `tests/fixtures/make_preset_guides.py`): each
//! preset's adjust values, the guides its `<a:rect>` uses, and the rectangle.

use std::collections::HashMap;
use std::sync::OnceLock;

use kurbo::Rect;

struct Def {
    adj: Vec<(&'static str, &'static str)>,
    guides: Vec<(&'static str, &'static str)>,
    rect: [&'static str; 4],
}

fn defs() -> &'static HashMap<&'static str, Def> {
    static DEFS: OnceLock<HashMap<&'static str, Def>> = OnceLock::new();
    DEFS.get_or_init(|| {
        let pairs = |s: &'static str| -> Vec<(&'static str, &'static str)> {
            s.split(';').filter(|x| !x.is_empty()).filter_map(|x| x.split_once('=')).collect()
        };
        include_str!("preset_text.txt")
            .lines()
            .filter(|l| !l.starts_with('#'))
            .filter_map(|l| {
                let f: Vec<&'static str> = l.split('|').collect();
                let r: Vec<&'static str> = f.get(3)?.split_whitespace().collect();
                Some((*f.first()?, Def { adj: pairs(f.get(1)?), guides: pairs(f.get(2)?), rect: [r.first()?, r.get(1)?, r.get(2)?, r.get(3)?] }))
            })
            .collect()
    })
}

fn eval(f: &str, v: &HashMap<&str, f64>) -> f64 {
    let mut p = f.split_whitespace();
    let op = p.next().unwrap_or("val");
    let a: Vec<f64> = p.map(|x| v.get(x).copied().or_else(|| x.parse().ok()).unwrap_or(0.0)).collect();
    let g = |i: usize| a.get(i).copied().unwrap_or(0.0);
    let rad = |x: f64| (x / 60000.0).to_radians();
    let div = |n: f64, d: f64| if d != 0.0 { n / d } else { 0.0 };
    let r = match op {
        "val" => g(0),
        "*/" => div(g(0) * g(1), g(2)),
        "+-" => g(0) + g(1) - g(2),
        "+/" => div(g(0) + g(1), g(2)),
        "?:" => {
            if g(0) > 0.0 {
                g(1)
            } else {
                g(2)
            }
        }
        "abs" => g(0).abs(),
        "at2" => g(1).atan2(g(0)).to_degrees() * 60000.0,
        "cat2" => g(0) * g(2).atan2(g(1)).cos(),
        "sat2" => g(0) * g(2).atan2(g(1)).sin(),
        "cos" => g(0) * rad(g(1)).cos(),
        "sin" => g(0) * rad(g(1)).sin(),
        "tan" => g(0) * rad(g(1)).tan(),
        "max" => g(0).max(g(1)),
        "min" => g(0).min(g(1)),
        "mod" => (g(0) * g(0) + g(1) * g(1) + g(2) * g(2)).sqrt(),
        "pin" => {
            if g(1) < g(0) {
                g(0)
            } else if g(1) > g(2) {
                g(2)
            } else {
                g(1)
            }
        }
        "sqrt" => g(0).max(0.0).sqrt(),
        _ => 0.0,
    };
    if r.is_finite() { r } else { 0.0 }
}

/// The standard's text rectangle for preset `name` in a `w` × `h` box with adjust values `adj`
/// (in handle order; missing ones take the standard's defaults). `None` for presets it doesn't
/// define or without a rectangle.
pub fn text_rect(name: &str, w: f64, h: f64, adj: &[f64]) -> Option<Rect> {
    let d = defs().get(name)?;
    let ss = w.min(h);
    let mut v: HashMap<&str, f64> = HashMap::with_capacity(64);
    for (k, x) in [
        ("w", w),
        ("h", h),
        ("l", 0.0),
        ("t", 0.0),
        ("r", w),
        ("b", h),
        ("ss", ss),
        ("ls", w.max(h)),
        ("hc", w / 2.0),
        ("vc", h / 2.0),
        ("cd2", 10_800_000.0),
        ("cd4", 5_400_000.0),
        ("cd8", 2_700_000.0),
        ("3cd4", 16_200_000.0),
        ("3cd8", 8_100_000.0),
        ("5cd8", 13_500_000.0),
        ("7cd8", 18_900_000.0),
    ] {
        v.insert(k, x);
    }
    const DIVS: [(&str, &str, &str, f64); 10] = [
        ("wd2", "hd2", "ssd2", 2.0),
        ("wd3", "hd3", "ssd3", 3.0),
        ("wd4", "hd4", "ssd4", 4.0),
        ("wd5", "hd5", "ssd5", 5.0),
        ("wd6", "hd6", "ssd6", 6.0),
        ("wd8", "hd8", "ssd8", 8.0),
        ("wd10", "hd10", "ssd10", 10.0),
        ("wd12", "hd12", "ssd12", 12.0),
        ("wd16", "hd16", "ssd16", 16.0),
        ("wd32", "hd32", "ssd32", 32.0),
    ];
    for (a, b, c, n) in DIVS {
        v.insert(a, w / n);
        v.insert(b, h / n);
        v.insert(c, ss / n);
    }
    for (i, (k, f)) in d.adj.iter().enumerate() {
        let x = adj.get(i).copied().filter(|x| x.is_finite()).unwrap_or_else(|| eval(f, &v));
        v.insert(k, x);
    }
    for (k, f) in &d.guides {
        let x = eval(f, &v);
        v.insert(k, x);
    }
    let get = |k: &str| v.get(k).copied().or_else(|| k.parse().ok()).unwrap_or(0.0);
    let [l, t, r, b] = d.rect.map(get);
    Some(Rect::new(l, t, r, b))
}
